def next_smallest_palindrome(n):
    # Convert the number to a string to easily manipulate its digits
    str_n = str(n)
    # Find the length of the number
    length = len(str_n)
    # If the number is a palindrome, increment the last digit and check for the next palindrome
    if str_n == str_n[::-1]:
        for i in range(length - 1, -1, -1):
            if str_n[i] != '9':
                str_n[i] = str(int(str_n[i]) + 1)
                break
        else:
            # If all digits are 9, prepend a 1 to the number
            str_n = '1' + '0' * (length - 1)
    else:
        # If the number is not a palindrome, find the next palindrome by incrementing the last digit
        for i in range(length - 1, -1, -1):
            if str_n[i] != '9':
                str_n[i] = str(int(str_n[i]) + 1)
                break
        # If all digits are 9, prepend a 1 to the number
        str_n = '1' + '0' * (length - 1)
    # Convert the string back to an integer and return it
    return int(str_n)
```

