def get_total_number_of_sequences(m, n):
    # Initialize a 2D list to store the number of sequences for each length and value
    dp = [[0 for _ in range(m + 1)] for _ in range(n + 1)]

    # Base case: There is one way to form a sequence of length 1 with any value
    for i in range(1, m + 1):
        dp[1][i] = 1

    # Fill the dp table
    for i in range(2, n + 1):
        for j in range(1, m + 1):
            # For each value j, the number of sequences is the sum of the sequences that can be formed with values less than or equal to j/2 and greater than or equal to j/2
            dp[i][j] = sum(dp[i - 1][k] for k in range(1, j // 2 + 1))

    # The total number of sequences of length n is the sum of the sequences that can be formed with values less than or equal to m
    return sum(dp[n][j] for j in range(1, m + 1))
```

