    if human_years == 1:
        return 15
    # Each subsequent year of a dog is equivalent to 4 human years
    elif human_years == 2:
        return 15 + 4
    else:
        # For each year after the first two, the dog's age is equivalent to 4 human years plus 3 more human years
        return 15 + 4 + (human_years - 2) * 3
