def max_sum_increasing_subseq(nums, i, k, j):
    # Initialize a 2D array to store the maximum sum of increasing subsequence
    dp = [[0] * (j + 1) for _ in range(i + 1)]

    # Fill the dp array
    for i in range(1, i + 1):
        for j in range(1, j + 1):
            if nums[i - 1] < nums[j - 1]:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + nums[i - 1])
            if nums[i - 1] < nums[k - 1]:
                dp[i][j] = max(dp[i][j], dp[i - 1][k - 1] + nums[i - 1])

    # The maximum sum of increasing subsequence from prefix until ith index and including kth element
    return dp[i][j]
```

