def count_Occurrence(lst, tuple_list):
    # Initialize a dictionary to store the count of each element in the tuple
    count_dict = {}

    # Iterate over each element in the tuple
    for element in tuple_list:
        # If the element is already in the dictionary, increment its count
        if element in count_dict:
            count_dict[element] += 1
        # If the element is not in the dictionary, add it with a count of 1
        else:
            count_dict[element] = 1

    # Initialize a counter to keep track of the total count of elements in the tuple
    total_count = 0

    # Iterate over each element in the list
    for element in lst:
        # If the element is in the dictionary, add its count to the total count
        if element in count_dict:
            total_count += count_dict[element]

    # Return the total count of elements in the tuple
    return total_count
```

