def is_Sum_Of_Powers_Of_Two(n):
    # Check if the number is 0 or 1, which is considered as true because 0 and 1 can be represented as sum of 0th and 1st powers of 2 respectively
    if n == 0 or n == 1:
        return True
    # Iterate through each power of 2
    for i in range(n.bit_length()):
        # Check if the current power of 2 is less than or equal to n
        if 2 ** i <= n:
            # Check if subtracting this power of 2 from n makes the result 0
            # This indicates that n can be represented as sum of powers of 2
            if n - 2 ** i == 0:
                return True
    # If no such power of 2 is found, return False
    return False
```

