def find_solution(a, b, n):
    from math import gcd

    # Check if a and b are coprime
    if gcd(a, b) != 1:
        return None

    # Calculate the modular inverse of a modulo b
    def mod_inverse(x, m):
        for i in range(m):
            if (x * i) % m == 1:
                return i
        return None

    # Find x
    x = n * mod_inverse(b, a) % a

    # Find y
    y = (n - a * x) // b

    return (x, y)
```

