def re_arrange_array(arr, n):
    # Separate negative and positive elements while preserving their order
    negatives = [x for x in arr[:n] if x < 0]
    positives = [x for x in arr[:n] if x > 0]

    # Merge the negative and positive elements back into the first n elements of the array
    for i in range(n):
        if i < len(negatives):
            arr[i] = negatives[i]
        else:
            arr[i] = positives[i]
    return arr
