    if m >= n:
        return 0
    # Base case: If n is 0 and m is 0, return 1
    if n == 0 and m == 0:
        return 1
    # Recursive relation to calculate Eulerian number
    return ((n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m))

