def get_total_number_of_sequences(m, n): 
    # Initialize a 2D list with zeros
    dp = [[0 for x in range(n + 1)] for x in range(m + 1)] 
    # Iterate over the range of m and n
    for i in range(1, m + 1): 
        for j in range(1, n + 1): 
            # Base case: If there's only one element in the sequence
            if j == 1: 
                dp[i][j] = i 
            else: 
                # Calculate the number of sequences by summing up the previous values
                dp[i][j] = dp[i - 1][j] + dp[i // 2][j - 1] 
    # Return the total number of sequences of length n with elements up to m
    return dp[m][n]
```

