def lps(s): 
    n = len(s) 
    L = [[0 for x in range(n)]for y in range(n)] 
    for i in range(n): 
        L[i][i] = 1
    cl = 2
    while cl <= n: 
        for i in range(n - cl + 1): 
            j = i + cl - 1
            if s[i] == s[j] and cl == 2: 
                L[i][j] = 2
            elif s[i] == s[j]: 
                L[i][j] = L[i + 1][j - 1] + 2
            else: 
                L[i][j] = max(L[i][j - 1], L[i + 1][j]); 
        cl += 1
    return L[0][n - 1]
```

