def max_sub_array_sum_repeated(arr, n, k):
    # Calculate the maximum subarray sum of the original array
    max_so_far = float('-inf')
    max_ending_here = 0
    for i in range(n):
        max_ending_here += arr[i]
        if max_so_far < max_ending_here:
            max_so_far = max_ending_here
        if max_ending_here < 0:
            max_ending_here = 0

    # Calculate the sum of the array
    array_sum = sum(arr)

    # If the array sum is positive, calculate the maximum sum of the modified array
    if array_sum > 0:
        return max_so_far + (array_sum * (k - 1))
    else:
        return max_so_far

# Test the function with the provided test case
assert max_sub_array_sum_repeated([10, 20, -30, -1], 4, 3) == 30
```
